         'plataforma' => ['Conferir as saídas "a conferir"', 'Aplicar a saída depois da prévia'], 'plataforma_en' => ['Check exits marked "to check"', 'Apply the exit after the preview'], 'site' => ['Postar de novo as semanas que mudaram'], 'site_en' => ['Post again the weeks that changed']],
        ['tela' => 'trocas', 'alvo' => '.kpis', 'titulo' => 'Trocas de página', 'titulo_en' => 'Page swaps',
