         'plataforma' => ['Marcar "Apaguei" e "Postei" em cada página'], 'plataforma_en' => ['Mark "Deleted" and "Posted" on each page'], 'site' => ['Delete Range a partir do corte', 'Colar o CSV de cada página'], 'site_en' => ['Delete Range from the cut-off', 'Paste each page\'s CSV']],
        ['tela' => 'colaboradores', 'alvo' => '.panel', 'titulo' => 'Colaboradores', 'titulo_en' => 'Employees',
         'texto' => 'Unidade, turno, núcleo, nível de SR e modelo de cada pessoa. Editar troca de núcleo e mostra antes o "de → para" e as vagas que fecham.', 'texto_en' => 'Each person\'s unit, shift, core, SR level and model. Editing changes the core and shows the "from → to" and the slots that close first.',
         'plataforma' => ['Manter o cadastro em dia antes de gerar'], 'plataforma_en' => ['Keep records up to date before generating'], 'site' => [], 'site_en' => []],
        ['tela' => 'tutorial', 'alvo' => '.tema', 'titulo' => 'Ajuda, tema e idioma', 'titulo_en' => 'Help, theme and language',
         'texto' => 'No menu: Glossário, FAQ, Tutorial e Changelog. No topo do menu troque o tema (claro, escuro, automático) e o idioma (PT/EN). Para praticar sem risco, ligue o Modo Treino.', 'texto_en' => 'In the menu: Glossary, FAQ, Tutorial and Changelog. At the top of the menu change the theme (light, dark, automatic) and the language (PT/EN). To practice safely, turn on Training mode.',
         'plataforma' => [], 'plataforma_en' => [], 'site' => [], 'site_en' => []],
        ['tela' => 'casais', 'alvo' => '.panel', 'titulo' => 'Folga juntos', 'titulo_en' => 'Days off together',
         'texto' => 'Associe as pessoas que precisam folgar nos mesmos dias (casais). A tabela mostra se o par já folga junto e propõe o ajuste do ciclo, que vale a partir da data escolhida.', 'texto_en' => 'Link the people who need the same days off (couples). The table shows whether the pair is already off together and suggests the cycle adjustment, valid from the chosen date.',
         'plataforma' => ['Aplicar o ajuste e recalcular as semanas a partir da data'], 'plataforma_en' => ['Apply the adjustment and recalculate the weeks from the date'], 'site' => [], 'site_en' => []],
        ['tela' => 'treinamento', 'alvo' => '.panel', 'titulo' => 'Treinamento de New Hires', 'titulo_en' => 'New Hire training',
         'texto' => 'Cole o e-mail do Treinamento: o sistema lê as turmas, recomenda as páginas para emprestar e gera a resposta. Turma confirmada entra na página 5C Schedule com -4 quando a semana é gerada.', 'texto_en' => 'Paste the Training e-mail: the system reads the classes, suggests pages to lend and writes the reply. A confirmed class goes on the 5C Schedule page with -4 when the week is generated.',
         'plataforma' => ['Confirmar as turmas e as páginas antes de gerar'], 'plataforma_en' => ['Confirm classes and pages before generating'], 'site' => ['Responder o e-mail do Treinamento'], 'site_en' => ['Reply to the Training e-mail']],
    ];
    $ordem = ['painel', 'colaboradores', 'aprovar', 'solicitacoes', 'saidas', 'treinamento', 'casais', 'gerar', 'grade:table.grade', 'horas', 'lideranca', 'grade:.kpis', 'grade:#postar', 'trocas', 'tutorial'];
    $porChave = [];
    foreach ($passos as $p) {
        $porChave[$p['tela'] === 'grade' ? 'grade:' . $p['alvo'] : $p['tela']] = $p;
    }
    $out = [];
    foreach ($ordem as $k) {
        if (isset($porChave[$k])) {
            $out[] = $porChave[$k];
            unset($porChave[$k]);
        }
    }
    return array_merge($out, array_values($porChave));
}

// Ações necessárias agora: o que está pendente na plataforma e no site da 5C, com link.
function escAcoesNecessarias(): array {
    $acoes = [];
    $seg = segundaDaSemana(date('Y-m-d'));
    foreach ([$seg, escMaisDias($seg, 7)] as $s) {
        $pub = escQ1('SELECT id, versao, subversao FROM ' . escT('esc_plano') . " WHERE semana_inicio = ? AND time_nome = '' AND status = 'PUBLICADO' ORDER BY id DESC LIMIT 1", [$s]);
        $atual = escPlanoAtual($s);
        $semana = escData($s);
        if (!$atual) {
            $acoes[] = ['onde' => 'plataforma', 'texto' => t('Gerar a escala da semana de {dia}', ['dia' => $semana]), 'link' => link_tela('gerar', ['semana' => $s])];
            continue;
        }
        if ($atual['status'] === 'RASCUNHO') {
            $acoes[] = ['onde' => 'plataforma', 'texto' => $pub ? t('Publicar o rascunho {versao} da semana de {dia} (há mudanças depois da publicada)', ['versao' => escPlanoRotulo($atual), 'dia' => $semana]) : t('Publicar a escala da semana de {dia}', ['dia' => $semana]), 'link' => link_tela('grade', ['plano' => (int) $atual['id']])];
        }
        if ($pub) {
            try {
                $paginas = (int) (escQ1('SELECT COUNT(DISTINCT page_id) AS n FROM ' . escT('esc_plano_alocacao') . ' WHERE plano_id = ? AND rep_code IS NOT NULL', [(int) $pub['id']])['n'] ?? 0);
                $postadas = (int) (escQ1('SELECT COUNT(*) AS n FROM ' . escT('esc_plano_postagem') . ' WHERE plano_id = ? AND postado_em IS NOT NULL', [(int) $pub['id']])['n'] ?? 0);
                if ($postadas === 0 && $paginas > 0) {
                    // Nenhuma marcada como postada: a Grade mostra quais mudaram e quais podem ficar.
                    $acoes[] = ['onde' => 'site', 'texto' => t('Postar a semana de {dia} no site da 5C ({versao} publicada, nada marcado como postado)', ['dia' => $semana, 'versao' => escPlanoRotulo($pub)]), 'link' => link_tela('grade', ['plano' => (int) $pub['id'], 'aba' => 'pagina']) . '#postar'];
                }
            } catch (Throwable $e) {
                // controle de postagem ainda não criado (ES_23)
            }
        }
    }
    $n = (int) (escQ1('SELECT COUNT(*) AS n FROM ' . escT('esc_indisponibilidade') . " WHERE status = 'PENDENTE'")['n'] ?? 0);
    if ($n) {
        $acoes[] = ['onde' => 'plataforma', 'texto' => t('Decidir {n} pedido(s) de indisponibilidade', ['n' => $n]), 'link' => link_tela('aprovar')];
    }
    if (escPolInstalada() && escPode('decidir')) {
        try {
            $n = count(escPolAvaliar(date('Y-m-d'))['sugestoes']);
            if ($n) {
                $acoes[] = ['onde' => 'plataforma', 'texto' => t('Decidir {n} troca(s) sugerida(s) pela política de páginas', ['n' => $n]), 'link' => link_tela('owners') . '#sugestoes-politica'];
            }
        } catch (Throwable $e) {
            // sem dados do Intraday agora: a tela Owners mostra o motivo
        }
    }
    if (escSolInstalada()) {
        $n = (int) (escQ1('SELECT COUNT(*) AS n FROM ' . escT('esc_solicitacao') . " WHERE status = 'PENDENTE'")['n'] ?? 0);
        if ($n) {
            $acoes[] = ['onde' => 'plataforma', 'texto' => t('Decidir {n} solicitação(ões) de SR', ['n' => $n]), 'link' => link_tela('solicitacoes')];
        }
    }
    try {
        $n = (int) (escQ1('SELECT COUNT(*) AS n FROM ' . escT('esc_hora_extra') . " WHERE status = 'INTERESSADO' AND dia >= CURDATE()")['n'] ?? 0);
        if ($n) {
            $acoes[] = ['onde' => 'plataforma', 'texto' => t('Decidir {n} interesse(s) de hora extra', ['n' => $n]), 'link' => link_tela('horas')];
        }
    } catch (Throwable $e) {
        // tabela ainda não criada (ES_14)
    }
    try {
        $ids = array_column(escQ("SELECT id FROM `5c_planning`.`fc_pagina_eventos` WHERE tipo = 'SAIDA' AND status <> 'CANCELADA' AND data_evento >= CURDATE() - INTERVAL 7 DAY"), 'id');
        if ($ids) {
            $conferidas = (int) (escQ1('SELECT COUNT(*) AS n FROM ' . escT('esc_saida_checagem') . " WHERE decisao <> 'PENDENTE' AND evento_id IN (" . escIn($ids) . ')', $ids)['n'] ?? 0);
            if (count($ids) > $conferidas) {
                $acoes[] = ['onde' => 'plataforma', 'texto' => t('Conferir {n} saída(s) de página', ['n' => count($ids) - $conferidas]), 'link' => link_tela('saidas')];
            }
        }
    } catch (Throwable $e) {
        appLog('warning', 'Ações necessárias: saídas', ['erro' => $e->getMessage()]);
    }
    return $acoes;
}
